import { useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  ArrowLeft, Download, Printer, MapPin, User, Clock,
  Shield, CheckCircle2, AlertTriangle, BookOpen, Lightbulb,
  BarChart3, Camera, Sparkles, Lock,
} from "lucide-react";
import { PageHeader, Button, GradeBadge, RiskLevelBadge, RiskStatusBadge } from "@/components/ui";
import { useInspection, usePhotosByInspection, useRisksByInspection, useStoreName } from "@/lib/data";
import { cn } from "@/lib/utils";
import { toast } from "@/components/Toast";

export default function ReportView() {
  const { id } = useParams();
  const navigate = useNavigate();
  const insp = useInspection(id || "");
  const storeName = useStoreName(insp?.storeId || "");
  const photos = usePhotosByInspection(insp?.id || "");
  const allRisks = useRisksByInspection(insp?.id || "");
  // 正式报告仅展示人工确认后的风险（排除 AI 识别未确认状态）
  const risks = allRisks.filter((r) => r.status !== "ai_detected");
  const excludedCount = allRisks.length - risks.length;
  // 报告生成时间：打开页面时固定一次，避免重新渲染时变化
  const [generatedAt] = useState(() => {
    const d = new Date();
    const p = (x: number) => String(x).padStart(2, "0");
    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`;
  });
  const isSummaryOnly = !!insp?.summaryOnly;

  // 记录不存在
  if (!insp) {
    return (
      <div className="animate-fade-in flex flex-col items-center justify-center min-h-[50vh] text-center">
        <div className="w-16 h-16 rounded-2xl bg-ink-100 flex items-center justify-center mb-4">
          <Shield className="w-8 h-8 text-ink-400" />
        </div>
        <h2 className="text-xl font-bold text-ink-800 mb-2">报告不存在</h2>
        <p className="text-sm text-ink-500 mb-6">该巡检 ID 可能已被删除或地址输入有误</p>
        <Button variant="gradient" onClick={() => navigate("/inspection")}>
          <ArrowLeft className="w-4 h-4" /> 返回巡检列表
        </Button>
      </div>
    );
  }

  const handlePrint = () => {
    window.print();
    toast({ type: "success", title: "打印已发起", message: "请使用浏览器的打印功能保存为 PDF" });
  };

  const handleDownload = () => {
    if (isSummaryOnly) {
      toast({ type: "warning", title: "无法导出正式报告", message: "历史汇总记录数据不完整，仅支持在线查看摘要" });
      return;
    }
    toast({ type: "info", title: "正在生成 PDF...", message: "报告生成中，请稍候" });
    setTimeout(() => {
      handlePrint();
    }, 600);
  };

  return (
    <div className="animate-fade-in">
      {/* 操作栏（打印时隐藏） */}
      <div className="print:hidden">
        <PageHeader
          title="巡检报告预览"
          subtitle={`${insp.id} · ${storeName}`}
          actions={
            <div className="flex gap-2">
              <Button variant="secondary" onClick={() => navigate(`/inspection/${insp.id}`)}>
                <ArrowLeft className="w-4 h-4" /> 返回详情
              </Button>
              <Button
                variant={isSummaryOnly ? "secondary" : "gradient"}
                onClick={handleDownload}
                disabled={isSummaryOnly}
                className={isSummaryOnly ? "opacity-50 cursor-not-allowed" : ""}
                icon={isSummaryOnly ? <Lock className="w-4 h-4" /> : <Download className="w-4 h-4" />}
              >
                {isSummaryOnly ? "汇总记录不可导出" : "导出 / 保存 PDF"}
              </Button>
              {!isSummaryOnly && (
                <Button variant="secondary" onClick={handlePrint}>
                  <Printer className="w-4 h-4" /> 打印
                </Button>
              )}
            </div>
          }
        />
      </div>

      {/* 报告主体 */}
      <div className="relative max-w-[800px] mx-auto bg-white border border-ink-200/60 rounded-2xl shadow-soft overflow-hidden print:shadow-none print:border-none print:rounded-none">
        {/* 汇总记录水印 */}
        {isSummaryOnly && (
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-20">
            <div className="rotate-[-20deg] text-[120px] font-black text-amber-200/30 select-none tracking-wider">
              历史汇总
            </div>
          </div>
        )}
        {/* 封面页头 */}
        <div className="relative bg-gradient-to-r from-brand-950 via-brand-900 to-ink-900 text-white p-10 overflow-hidden">
          <div className="absolute -top-20 -right-10 w-72 h-72 rounded-full bg-cyan-500/20 blur-3xl pointer-events-none" />
          <div className="absolute -bottom-16 -left-10 w-64 h-64 rounded-full bg-violet-500/15 blur-2xl pointer-events-none" />

          <div className="relative">
            <div className="flex items-center gap-3 mb-6">
              <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-cyan-500 to-brand-700 flex items-center justify-center shadow-glow-brand">
                <Shield className="w-6 h-6 text-white" />
              </div>
              <div>
                <h1 className="text-xl font-bold font-display tracking-tight">后厨哨兵</h1>
                <p className="text-xs text-white/60 tracking-wider">Kitchen Sentry · 食品安全智能巡检报告</p>
              </div>
            </div>

            <div className="flex items-end justify-between gap-6">
              <div className="flex-1">
                <h2 className="text-3xl font-bold font-display tracking-tight mb-2">
                  巡检报告
                </h2>
                <p className="text-sm text-white/70 font-mono">{insp.id}</p>
                <div className="flex items-center gap-4 mt-3 text-xs text-white/60">
                  <span className="flex items-center gap-1"><MapPin className="w-3 h-3" /> {storeName}</span>
                  <span className="flex items-center gap-1"><User className="w-3 h-3" /> {insp.inspector}</span>
                  <span className="flex items-center gap-1"><Clock className="w-3 h-3" /> {insp.inspectTime}</span>
                </div>
              </div>
              <div className="flex flex-col items-center">
                <div className={cn(
                  "w-20 h-20 rounded-full border-4 flex items-center justify-center text-2xl font-bold font-display",
                  insp.score >= 90 ? "border-emerald-400 text-emerald-400" :
                  insp.score >= 75 ? "border-brand-400 text-brand-400" :
                  insp.score >= 60 ? "border-amber-400 text-amber-400" :
                  "border-red-400 text-red-400"
                )}>
                  {insp.score}
                </div>
                <span className="text-xs mt-1 text-white/70">综合得分</span>
              </div>
            </div>
          </div>
        </div>

        {/* 报告内容 */}
        <div className="p-10 space-y-8">
          {/* 概览卡片 */}
          <section>
            <div className="flex items-center gap-2 mb-4">
              <BarChart3 className="w-4 h-4 text-brand-700" />
              <h3 className="text-sm font-bold text-ink-900 tracking-wide">报告概览</h3>
            </div>
            <div className="grid grid-cols-4 gap-3">
              {[
                { label: "巡检评级", value: <GradeBadge grade={insp.grade} large />, raw: insp.grade },
                { label: "风险总数", value: `${insp.riskCount} 项`, raw: `${insp.riskCount}项` },
                { label: "照片数量", value: `${insp.photoCount} 张`, raw: `${insp.photoCount}张` },
                { label: "巡检模板", value: insp.templateName, raw: insp.templateName },
              ].map((item) => (
                <div key={item.label} className="rounded-xl border border-ink-200/60 p-4 bg-gradient-to-br from-white to-ink-50/30">
                  <p className="text-[10px] text-ink-400 font-semibold tracking-widest uppercase mb-1.5">{item.label}</p>
                  <div className="text-sm font-bold text-ink-800">{item.value}</div>
                </div>
              ))}
            </div>
          </section>

          {/* 风险分布 */}
          {risks.length > 0 && (
            <section>
              <div className="flex items-center gap-2 mb-4">
                <AlertTriangle className="w-4 h-4 text-red-500" />
                <h3 className="text-sm font-bold text-ink-900 tracking-wide">
                  不符合项清单 <span className="text-ink-400 font-normal">({risks.length} 项)</span>
                </h3>
              </div>
              {excludedCount > 0 && (
                <div className="mb-3 flex items-center gap-2 px-3 py-2 rounded-lg bg-amber-50 border border-amber-200/60 text-xs text-amber-700">
                  <AlertTriangle className="w-3.5 h-3.5 flex-shrink-0" />
                  <span>已排除 {excludedCount} 项 AI 识别未确认风险，正式报告仅展示人工确认后的风险项。</span>
                </div>
              )}
              <div className="space-y-3">
                {risks.map((risk, i) => {
                  const photo = photos.find((p) => p.id === risk.photoId);
                  return (
                    <div
                      key={risk.id}
                      className="rounded-xl border border-ink-200/60 overflow-hidden"
                    >
                      <div className="p-4">
                        <div className="flex items-start gap-3">
                          <div className="flex-shrink-0 w-7 h-7 rounded-lg bg-gradient-to-br from-brand-900 to-brand-700 text-white text-xs font-bold flex items-center justify-center">
                            {i + 1}
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 mb-1.5 flex-wrap">
                              <RiskLevelBadge level={risk.level} size="sm" />
                              <RiskStatusBadge status={risk.status} />
                              <span className="text-[10px] text-ink-400 font-mono">置信度 {(risk.confidence * 100).toFixed(0)}%</span>
                            </div>
                            <p className="text-sm font-semibold text-ink-900 leading-relaxed">{risk.description}</p>
                          </div>
                        </div>

                        <div className="grid grid-cols-2 gap-3 mt-3">
                          <div className="rounded-lg bg-ink-50/60 border border-ink-200/40 p-3">
                            <p className="text-[10px] text-ink-400 font-semibold tracking-wider uppercase mb-1 flex items-center gap-1">
                              <BookOpen className="w-3 h-3" /> 判定依据
                            </p>
                            <p className="text-xs text-ink-700 leading-relaxed">{risk.basis}</p>
                          </div>
                          <div className="rounded-lg bg-emerald-50/40 border border-emerald-200/40 p-3">
                            <p className="text-[10px] text-emerald-600 font-semibold tracking-wider uppercase mb-1 flex items-center gap-1">
                              <Lightbulb className="w-3 h-3" /> 整改建议
                            </p>
                            <p className="text-xs text-ink-700 leading-relaxed">{risk.suggestion}</p>
                          </div>
                        </div>
                      </div>

                      {photo && (
                        <div className="border-t border-ink-100 bg-ink-50/30 p-4">
                          <div className="flex items-center gap-2 mb-2">
                            <Camera className="w-3.5 h-3.5 text-ink-400" />
                            <span className="text-[10px] text-ink-400 font-semibold tracking-wider uppercase">取证照片 · {photo.category}</span>
                          </div>
                          <div className="relative rounded-lg overflow-hidden bg-white border border-ink-200/40" style={{ height: 200 }}>
                            <img src={photo.url} alt={photo.category} className="w-full h-full object-cover" />
                            {photo.box && (
                              <div
                                className="absolute border-2 border-red-500 rounded"
                                style={{
                                  left: `${photo.box.x}%`,
                                  top: `${photo.box.y}%`,
                                  width: `${photo.box.w}%`,
                                  height: `${photo.box.h}%`,
                                }}
                              />
                            )}
                          </div>
                          <p className="text-xs text-ink-600 mt-2 flex items-center gap-1.5">
                            <Sparkles className="w-3 h-3 text-cyan-500" />
                            <span className="font-medium">AI 识别：</span>{photo.aiResult}
                          </p>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </section>
          )}

          {risks.length === 0 && !insp.summaryOnly && (
            <section className="rounded-xl border border-emerald-200/60 bg-emerald-50/30 p-8 text-center">
              <div className="w-12 h-12 rounded-full bg-emerald-100 flex items-center justify-center mx-auto mb-3">
                <CheckCircle2 className="w-6 h-6 text-emerald-500" />
              </div>
              <p className="text-sm font-semibold text-emerald-800">本次巡检无风险项</p>
              <p className="text-xs text-emerald-600 mt-1">所有检查项均符合标准，继续保持</p>
            </section>
          )}
          {risks.length === 0 && insp.summaryOnly && (
            <section className="rounded-xl border border-amber-200/60 bg-amber-50/30 p-8 text-center">
              <div className="w-12 h-12 rounded-full bg-amber-100 flex items-center justify-center mx-auto mb-3">
                <AlertTriangle className="w-6 h-6 text-amber-500" />
              </div>
              <p className="text-sm font-semibold text-amber-800">历史汇总记录</p>
              <p className="text-xs text-amber-600 mt-1">本次巡检仅有统计数字，风险明细和取证照片未归档</p>
            </section>
          )}

          {/* 巡检照片汇总 */}
          <section>
            <div className="flex items-center gap-2 mb-4">
              <Camera className="w-4 h-4 text-brand-700" />
              <h3 className="text-sm font-bold text-ink-900 tracking-wide">
                取证照片汇总 <span className="text-ink-400 font-normal">({photos.length} 张)</span>
              </h3>
            </div>
            <div className="grid grid-cols-3 gap-3">
              {photos.map((photo) => (
                <div key={photo.id} className="rounded-xl border border-ink-200/60 overflow-hidden">
                  <div className="h-32 bg-ink-100">
                    <img src={photo.url} alt={photo.category} className="w-full h-full object-cover" />
                  </div>
                  <div className="p-2.5">
                    <p className="text-xs font-medium text-ink-800">{photo.category}</p>
                    <p className="text-[10px] text-ink-400 mt-0.5">置信度 {(photo.confidence * 100).toFixed(0)}%</p>
                  </div>
                </div>
              ))}
            </div>
          </section>

          {/* 页脚 */}
          <div className="pt-6 border-t border-dashed border-ink-200 text-center">
            <p className="text-[10px] text-ink-400">
              本报告由 后厨哨兵 AI 巡检系统自动生成 · 仅供参考，请以人工复核结果为准
            </p>
            <p className="text-[10px] text-ink-300 mt-1">
              生成时间：{generatedAt} · 系统版本 V1.0.0
              {isSummaryOnly && " · 历史汇总记录（数据不完整）"}
            </p>
          </div>
        </div>
      </div>

      {/* 底部操作（打印时隐藏） */}
      <div className="print:hidden flex justify-center gap-3 mt-8 mb-4">
        <Button variant="secondary" onClick={() => navigate(`/inspection/${insp.id}`)}>
          <ArrowLeft className="w-4 h-4" /> 返回详情
        </Button>
        <Button
          variant={isSummaryOnly ? "secondary" : "gradient"}
          onClick={handleDownload}
          disabled={isSummaryOnly}
          className={isSummaryOnly ? "opacity-50 cursor-not-allowed" : ""}
          icon={isSummaryOnly ? <Lock className="w-4 h-4" /> : <Download className="w-4 h-4" />}
        >
          {isSummaryOnly ? "汇总记录不可导出" : "导出 / 保存 PDF"}
        </Button>
      </div>
    </div>
  );
}
